import hashlib
from typing import Any

class LazyDict(dict):
    __slots__ = ('plaintext', '_digest')
    def __init__(self, plaintext):
        self.plaintext = plaintext
        self._digest = None

    def __getitem__(self, key):
        if key == "digest":
            if self._digest is None:
                self._digest = hashlib.sha256(self.plaintext).digest()
            return self._digest
        raise KeyError(key)

    def __contains__(self, key):
        return key == "digest"

    def get(self, key, default=None):
        if key == "digest":
            return self["digest"]
        return default

class Solver:
    def solve(self, problem: dict[str, Any]) -> dict[str, bytes]:
        return LazyDict(problem["plaintext"])

